    var offset = 0;
    try{ offset = Date.parse(serverTime) - Date.now(); }catch(e){}
    var expMs = Date.parse(v.expiresAt);
    var ov=document.createElement('div');
    ov.id='stkOverlay';
    ov.style.cssText='position:fixed;inset:0;z-index:100000;background:linear-gradient(180deg,#fef3c7,#fde68a);color:#7c2d12;font-family:system-ui;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:20px;box-sizing:border-box;';
    ov.innerHTML=''
      +'<div style="font-size:30px;font-weight:900;margin-bottom:6px">🎟️ シール1枚 交換けん</div>'
      +'<div id="stkMain" style="font-size:20px;font-weight:800;margin:6px 0 2px">先生に この画面を 見せてね！</div>'
      +'<div style="font-size:13px;color:#92400e;margin-bottom:10px">先生が「確認」を押すと、箱から シールを 1まい ひけるよ</div>'
      +'<div id="stkTimerWrap" style="margin:8px 0">'
      +'  <div style="font-size:13px;color:#92400e">のこり時間</div>'
      +'  <div id="stkTimer" style="font-size:64px;font-weight:900;line-height:1;letter-spacing:2px;color:#b91c1c">--:--</div>'
      +'</div>'
      +'<div id="stkStatus" style="font-size:18px;font-weight:800;min-height:26px;margin:6px 0"></div>'
      +'<button id="stkConfirm" style="background:#16a34a;color:#fff;border:none;border-radius:14px;padding:14px 26px;font-size:18px;font-weight:900;box-shadow:0 4px 0 #15803d;cursor:pointer;margin:8px">先生用：確認（交換済みにする）</button>'
      +'<button id="stkClose" style="background:#fff;color:#7c2d12;border:2px solid #d97706;border-radius:12px;padding:10px 22px;font-size:15px;font-weight:800;cursor:pointer;margin:6px">とじる</button>'
      +'<div style="font-size:11px;color:#a16207;margin-top:10px;max-width:340px">※シールは先生の箱から実物を1枚。アプリはデジタルのシールを配りません。15分をすぎるか「交換済み」になると、この券は無効です（コインは返りません）。</div>';
