    function setExpired(){ if(_t){clearInterval(_t);_t=null;} if(timerEl){timerEl.textContent='0:00';timerEl.style.color='#6b7280';} if(mainEl)mainEl.textContent='時間ぎれ'; if(statusEl){ statusEl.style.color='#6b7280'; statusEl.textContent='⌛ 期限ぎれ（無効）— コインは返りません'; } if(confirmBtn)confirmBtn.style.display='none'; }

