    card.style.cssText='background:#fffbeb;';
    card.innerHTML=''
      +'<div class="flex items-center gap-3">'
      +'  <div class="text-3xl">🎟️</div>'
      +'  <div class="flex-1"><div class="font-bold text-base">シール1枚 交換けん</div>'
      +'  <div class="text-xs text-gray-600">先生に見せて、箱からシールを1枚！（1日1回）</div></div>'
      +'</div>'
      +'<div class="mt-1 bg-yellow-100 text-yellow-800 text-xs px-2 py-1 rounded-full w-fit">💰 300 コイン</div>'
      +'<div class="stk-cta" style="margin-top:6px;color:#fff;background:#f59e0b;border-radius:10px;padding:8px 10px;font-weight:800;font-size:13px;text-align:center">🎟️ 300コインで こうにゅう</div>';
    card.addEventListener('click', function(){ if(_boughtToday) openCurrent(); else if(!_stickerOn){ alert('いまは このクラスでは つかえません。'); } else doBuy(); });
