        //      ・バックスラッシュを含まない（ブラウザが / に正規化して //evil.com になる）
        var _bs = String.fromCharCode(92);
        var _safeNext = '';
        if (_next.length > 1 && _next.charAt(0) === '/' && _next.charAt(1) !== '/' && _next.indexOf(_bs) < 0) {
          _safeNext = _next;
        }
        if(_safeNext) { location.href = _safeNext; }
