      function _aiBodyLines(data){ var ov=data.overview||{}; var _sg5=(data.student&&data.student.grade)||null; var L=[]; if(_sg5) L.push('【学年】'+_sg5+'年生'); L.push('【基本統計】'); L.push('・提出回数: '+(ov.totalSubmissions||0)+'回'); L.push('・平均学習時間: '+(ov.avgMinutes||0)+'分'); L.push('・学習満足度（☀️の割合）: '+(ov.sunRate||0)+'%'); L.push('・現在の連続提出: '+(ov.currentStreak||0)+'日 / 最長連続: '+(ov.maxStreak||0)+'日'); if(ov.firstDate) L.push('・記録期間: '+ov.firstDate+' 〜 '+ov.lastDate); if(ov.totalMinutes!=null) L.push('・合計学習時間: '+ov.totalMinutes+'分（約'+Math.round((ov.totalMinutes||0)/60)+'時間）'); if(ov.returnRate!=null) L.push('・先生からの返却率: '+ov.returnRate+'%'); if(ov.submissionRate&&ov.submissionRate.show){ var _sr2=ov.submissionRate; L.push('・家庭学習の提出率: '+(_sr2.overall!=null?_sr2.overall+'%':'-')+'（直近約4週 '+(_sr2.recent!=null?_sr2.recent+'%':'-')+' / その前 '+(_sr2.prev!=null?_sr2.prev+'%':'-')+'）'); if(_sr2.trend==='down') L.push('・[要注意] 提出率が下がってきている → 正直に指摘し次の一歩を促す'); else if(_sr2.trend==='up') L.push('・提出率が上がってきている → 認めてほめる'); if(_sr2.overall!=null&&_sr2.overall<60) L.push('・[要注意] 提出率が低め（'+_sr2.overall+'%）→ ぼかさず具体的に、小さな目標を示す'); } var tw=(ov.sunCount||0)+(ov.cloudCount||0)+(ov.rainCount||0); if(tw>0) L.push('・満足度の内訳: ☀️'+(ov.sunCount||0)+'回 / ☁️'+(ov.cloudCount||0)+'回 / 🌧️'+(ov.rainCount||0)+'回'); if(data.subjects&&data.subjects.length){ var _sg6=(data.student&&data.student.grade)||null; L.push(''); L.push('【教科別の正答率（取り組み量の多い順／対象学年つき）】'); L.push('※「1問あたり」は 同じ問題を何回解いたかです。ここが大きい単元の高い正答率は、覚えているだけかもしれません。'); for(var j=0;j<data.subjects.length;j++){ var su=data.subjects[j]; var _ug6=_unitGrade(su.unit); var _lab6=_gradeLabel(_gradeClass(_sg6,_ug6))||'対象学年不明'; L.push('・'+_unitJa(su.unit)+'（'+(_ug6?('対象'+_ug6+'年・'):'')+_lab6+'）: 正答率'+su.rate+'%（のべ'+su.total+'問／問題の種類'+(su.kinds||'?')+'／1問あたり'+(su.repeatPer==null?'?':su.repeatPer)+'回'+((su.repeatPer!=null&&su.repeatPer>=5)?'・周回ぎみ':'')+'）'); } } if(data.teacherNotes&&data.teacherNotes.length){ L.push(''); L.push('【先生の観察メモ（授業中の様子・教師向け）】'); for(var tn=0;tn<Math.min(data.teacherNotes.length,15);tn++){ var nt=data.teacherNotes[tn]; if(nt && nt.aiOk===false) continue; L.push('・'+(nt.dayKey||'')+' '+(nt.subject?'['+nt.subject+'] ':'')+(window._qnMask?window._qnMask(nt.body||''):(nt.body||''))); } } if(data.classNotes&&data.classNotes.length){ L.push(''); L.push('【クラス全体の授業メモ（先生が書いた授業の記録・この子だけの話ではありません）】'); for(var cn=0;cn<Math.min(data.classNotes.length,10);cn++){ var cnt=data.classNotes[cn]; L.push('・'+(cnt.dayKey||'')+' '+(window._qnMask?window._qnMask(cnt.body||''):(cnt.body||''))); } } if(data.streaks&&data.streaks.length){ L.push(''); L.push('【連続提出の記録（上位）】'); for(var k=0;k<Math.min(data.streaks.length,3);k++){ L.push('・'+data.streaks[k].length+'日連続'); } } if(data.recentSubmissions&&data.recentSubmissions.length){ L.push(''); L.push('【直近の学習記録】'); for(var n=0;n<Math.min(data.recentSubmissions.length,10);n++){ var rs=data.recentSubmissions[n]; var w=rs.end_weather==='sun'?'☀️':rs.end_weather==='cloud'?'☁️':rs.end_weather==='rain'?'🌧️':'❓'; var line='・'+(rs.day_key||'')+' '+w+' '+(rs.todo||'')+'（'+(rs.minutes||0)+'分）'; if(rs.weather_reason) line+=' ふりかえり:'+rs.weather_reason; L.push(line); } } if(data.testScores&&data.testScores.length){ L.push(''); L.push('【テストの記録（今年度・全期間）】'); for(var tsx=0;tsx<data.testScores.length;tsx++){ var tt2=data.testScores[tsx]; L.push('・'+(tt2.testDate||'')+' '+(tt2.subject||'')+' '+(tt2.testName||'')+'：'+(tt2.score==null?'-':tt2.score)+'/'+(tt2.maxScore||100)+(tt2.pct!=null?'（'+tt2.pct+'%）':'')+(tt2.comment?' 先生:'+tt2.comment:'')); } } if(data.records&&data.records.length){ L.push(''); L.push('【ポートフォリオ（取り込んだプリント・成果物・先生の評価◎○△）／4月からの全期間】'); L.push('※日付は「取り込んだ日」です。古いものを今週の出来事として書かないでください。'); L.push('※「前に渡した材料」と書いてあるものは、前のカルテでもうほめています。二度目はほめないでください。'); var _rkj=function(k){ return k==='test'?'テスト':k==='report'?'まとめ':k==='reflect'?'振り返り':'その他'; }; for(var rpx=0;rpx<data.records.length;rpx++){ var rc2=data.records[rpx]; var _ev2=((rc2.evalRank?'／評価:'+rc2.evalRank:'')+((rc2.evalComment&&String(rc2.evalComment).trim())?'／評価コメント:'+rc2.evalComment:'')) /* IMPEVAL_G_V1 評定が空でも評価コメントは渡す */; var _ln2='・['+_rkj(rc2.type)+'] '+(rc2.title||'(無題)')+'（取り込み '+(rc2.importedOn||rc2.dayKey||'日付不明')+(rc2.unit?'／'+rc2.unit:'')+_ev2+(rc2.used?'／前に渡した材料':'')+'）'; if(rc2.body&&String(rc2.body).trim()) _ln2+=' 本文:'+rc2.body; if(rc2.reflection&&String(rc2.reflection).trim()) _ln2+=' ／振り返り:'+rc2.reflection; L.push(_ln2); } } return L; }
      function _normId(s){ return String(s==null?'':s).replace(/[Ａ-Ｚａ-ｚ０-９]/g,function(c){return String.fromCharCode(c.charCodeAt(0)-65248);}).replace(/[\\s　]/g,'').toLowerCase(); }
      function _parseAiBlocks(raw){ var lines=String(raw||'').split(/\\r?\\n/); var blocks=[]; var cur=null; var re=/^[\\s　]*[=＝]{2,}[\\s　]*[\\[［]\\s*([^\\]］]+?)\\s*[\\]］]/; for(var i=0;i<lines.length;i++){ var m=lines[i].match(re); if(m){ if(cur) blocks.push(cur); cur={id:m[1],lines:[]}; } else if(cur){ cur.lines.push(lines[i]); } } if(cur) blocks.push(cur); return blocks.map(function(b){ return {id:b.id, body:b.lines.join(String.fromCharCode(10)).replace(/^\\s+|\\s+$/g,'')}; }); }
